import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { DomSanitizer } from '@angular/platform-browser';
import { Router } from '@angular/router';
import { AlertController, LoadingController, ToastController } from '@ionic/angular';
import { GResponse } from 'src/app/core/common/GResponse';
import { SharedIonic } from 'src/app/core/common/SharedIonic';
import { Urls } from 'src/app/core/common/Urls';
import { CourseService } from 'src/app/data/service/course/course.service';
import { SliderService } from 'src/app/data/service/site/Slider.service';
import { VehicleProfile, VehicleProfileStore } from '../vehicle-profile/vehicle-profile.store';

interface CompressionQuenchResult {
  sweptVolumePerCylinderCc: number;
  totalDisplacementCc: number;
  gasketVolumeCc: number;
  deckVolumeCc: number;
  clearanceVolumeCc: number;
  staticCompressionRatio: number;
  quenchMm: number;
  quenchInches: number;
}

interface FieldDef {
  key: string;
  control: string;
  label: string;
  unit: string;
}

interface ResultItemDef {
  label: string;
  value: number | string;
  unit: string;
}

@Component({
  selector: 'app-compression-quench',
  templateUrl: './compression-quench.component.html',
  styleUrls: ['./compression-quench.component.scss'],
})
export class CompressionQuenchComponent implements OnInit {

  isShow = false;
  isCheck = true;
  profiles: VehicleProfile[] = [];
  selectedProfileId = '';
  profileNotice = '';
  private loadedProfileUpdatedAt = '';
  form: FormGroup;
  result: CompressionQuenchResult | null = null;

  blockFields: FieldDef[] = [
    { key: 'bore', control: 'boreMm', label: 'قطر سیلندر (Bore)', unit: 'mm' },
    { key: 'stroke', control: 'strokeMm', label: 'کورس پیستون (Stroke)', unit: 'mm' },
    { key: 'cylinders', control: 'cylinders', label: 'تعداد سیلندر', unit: '' },
    { key: 'chamber', control: 'chamberVolumeCc', label: 'حجم اتاق احتراق سرسیلندر', unit: 'cc' },
    { key: 'piston', control: 'pistonVolumeCc', label: 'حجم گودی یا برجستگی پیستون', unit: 'cc' },
  ];

  gasketFields: FieldDef[] = [
    { key: 'gasketBore', control: 'gasketBoreMm', label: 'قطر داخلی واشر', unit: 'mm' },
    { key: 'gasketThickness', control: 'gasketThicknessMm', label: 'ضخامت فشرده‌شده واشر', unit: 'mm' },
    { key: 'deck', control: 'deckClearanceMm', label: 'فاصله پیستون تا سطح بلوک (Deck)', unit: 'mm' },
  ];

  constructor(private fb: FormBuilder,
    private router: Router,
    public alertController: AlertController,
    private sanitizer: DomSanitizer,
    public loadingController: LoadingController,
    public toastController: ToastController,
    private courseService: CourseService,
    private siteService: SliderService) {

    this.isShow = false;
    this.check();
  }

  ionViewWillEnter(): void {
    this.profiles = VehicleProfileStore.list();
    const active = VehicleProfileStore.active();
    if (active && this.form && (active.id !== this.selectedProfileId ||
      active.updatedAt !== this.loadedProfileUpdatedAt)) {
      this.applyProfile(active.id);
    }
  }

  applyProfile(id: string): void {
    const profile = this.profiles.find(item => item.id === id);
    if (!profile || !this.form) { return; }
    const values = VehicleProfileStore.toolValues(profile, 'compression-quench');
    let applied = 0;
    Object.keys(values).forEach(key => {
      const control = this.form.get(key);
      if (!control) { return; }
      const previous = control.value;
      control.setValue(values[key], { emitEvent: false });
      if (control.invalid) { control.setValue(previous, { emitEvent: false }); }
      else { applied++; }
    });

    this.form.updateValueAndValidity();
    this.profileNotice = `${applied} مقدار از پروفایل اعمال شد؛ سایر ورودی‌ها پیش‌فرض ابزارند.`;
    this.selectedProfileId = id;
    this.loadedProfileUpdatedAt = profile.updatedAt;
    try { VehicleProfileStore.select(id); } catch { /* Local storage may be disabled. */ }
    this.calculate();
  }

  async check() {

    SharedIonic.loading(this.loadingController);

    this.siteService.GetTunerPlusById(36).subscribe(
      res => {
        if (res.status === GResponse.SuccessStatus) {

          if (res.data.isActive) {

            if (!res.data.isFree) {

              this.courseService.GetUserCoursesId().subscribe(
                ress => {
                  if (ress.status === GResponse.SuccessStatus) {
                    let found = false;
                    res.data.courseIds.forEach(courseId => {

                      if (ress.data.find(n => n == courseId)) {
                        found = true;

                        this.courseService.GetUserTunerPlusAccess().subscribe(
                          resss => {
                            if (resss.status === GResponse.SuccessStatus) {

                              SharedIonic.dismissLoading(this.loadingController);
                              this.isCheck = false;
                              this.isShow = true;
                            } else {
                              this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                              SharedIonic.dismissLoading(this.loadingController);
                            }
                          },
                          errs => {
                            this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                            SharedIonic.dismissLoading(this.loadingController);
                          }
                        );
                      }
                    });

                    if (!found) {
                      this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                      SharedIonic.dismissLoading(this.loadingController);
                    }

                  } else {
                    this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                    SharedIonic.dismissLoading(this.loadingController);
                  }
                },
                errs => {
                  this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                  SharedIonic.dismissLoading(this.loadingController);
                }
              );
            } else {
              SharedIonic.dismissLoading(this.loadingController);
              this.isCheck = false;
              this.isShow = true;
            }
          } else {
            this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
            SharedIonic.dismissLoading(this.loadingController);
          }
        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      err => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );
  }

  ngOnInit(): void {
    this.form = this.fb.group({
      boreMm: [78.5, [Validators.required, Validators.min(1)]],
      strokeMm: [82, [Validators.required, Validators.min(1)]],
      cylinders: [4, [Validators.required, Validators.min(1), Validators.max(16)]],
      chamberVolumeCc: [35, [Validators.required, Validators.min(1)]],
      pistonVolumeCc: [0, [Validators.required, Validators.min(-100), Validators.max(100)]],
      gasketBoreMm: [80, [Validators.required, Validators.min(1)]],
      gasketThicknessMm: [1.2, [Validators.required, Validators.min(0.1), Validators.max(5)]],
      deckClearanceMm: [0.2, [Validators.required, Validators.min(-2), Validators.max(5)]],
    });
    this.profiles = VehicleProfileStore.list();
    const active = VehicleProfileStore.active();
    if (active) { this.applyProfile(active.id); }

    this.form.valueChanges.subscribe(() => this.calculate());
    this.calculate();
  }

  calculate(): void {
    if (this.form.invalid) {
      this.result = null;
      return;
    }

    const value = this.form.getRawValue();
    const boreMm = Number(value.boreMm);
    const strokeMm = Number(value.strokeMm);
    const cylinders = Number(value.cylinders);
    const chamberVolumeCc = Number(value.chamberVolumeCc);
    const pistonVolumeCc = Number(value.pistonVolumeCc);
    const gasketBoreMm = Number(value.gasketBoreMm);
    const gasketThicknessMm = Number(value.gasketThicknessMm);
    const deckClearanceMm = Number(value.deckClearanceMm);

    const sweptVolumePerCylinderCc = this.cylinderVolumeCc(boreMm, strokeMm);
    const gasketVolumeCc = this.cylinderVolumeCc(gasketBoreMm, gasketThicknessMm);
    const deckVolumeCc = this.cylinderVolumeCc(boreMm, deckClearanceMm);
    const clearanceVolumeCc = chamberVolumeCc + pistonVolumeCc + gasketVolumeCc + deckVolumeCc;

    if (clearanceVolumeCc <= 0) {
      this.result = null;
      return;
    }

    const quenchMm = gasketThicknessMm + deckClearanceMm;
    this.result = {
      sweptVolumePerCylinderCc: this.round(sweptVolumePerCylinderCc, 2),
      totalDisplacementCc: this.round(sweptVolumePerCylinderCc * cylinders, 2),
      gasketVolumeCc: this.round(gasketVolumeCc, 2),
      deckVolumeCc: this.round(deckVolumeCc, 2),
      clearanceVolumeCc: this.round(clearanceVolumeCc, 2),
      staticCompressionRatio: this.round((sweptVolumePerCylinderCc + clearanceVolumeCc) / clearanceVolumeCc, 2),
      quenchMm: this.round(quenchMm, 2),
      quenchInches: this.round(quenchMm / 25.4, 3),
    };
  }

  reset(): void {
    this.form.reset({
      boreMm: 78.5,
      strokeMm: 82,
      cylinders: 4,
      chamberVolumeCc: 35,
      pistonVolumeCc: 0,
      gasketBoreMm: 80,
      gasketThicknessMm: 1.2,
      deckClearanceMm: 0.2,
    });
  }

  get quenchMessage(): string {
    const quenchMm = this.result?.quenchMm;
    if (quenchMm === undefined) { return 'تمام مقادیر را وارد کنید تا نتیجه نمایش داده شود.'; }
    if (quenchMm < 0.65) { return 'فاصله کوئنچ بسیار کم است؛ لقی واقعی قطعات، کشش شاتون و انبساط حرارتی را با دقت بررسی کنید.'; }
    if (quenchMm <= 1.15) { return 'فاصله کوئنچ در محدوده رایج موتورهای پرفورمنس خیابانی قرار دارد.'; }
    if (quenchMm <= 1.5) { return 'فاصله کوئنچ نسبتاً باز است؛ فاصله پیستون تا سطح بلوک و ضخامت فشرده‌شده واشر را دوباره اندازه بگیرید.'; }
    return 'فاصله کوئنچ زیاد است و ممکن است اثر فشردن مخلوط سوخت و هوا و مقاومت در برابر ناک را کاهش دهد.';
  }

  get quenchColor(): string {
    const quenchMm = this.result?.quenchMm;
    if (quenchMm === undefined || quenchMm < 0.65 || quenchMm > 1.5) { return 'danger'; }
    return quenchMm <= 1.15 ? 'success' : 'warning';
  }

  get quenchStatusLabel(): string {
    const quenchMm = this.result?.quenchMm;
    if (quenchMm === undefined) { return 'بدون نتیجه'; }
    if (quenchMm < 0.65) { return 'کمتر از بازه مرجع'; }
    if (quenchMm <= 1.15) { return 'در بازه مرجع'; }
    if (quenchMm <= 1.5) { return 'بازتر از بازه مرجع'; }
    return 'بیشتر از بازه مرجع';
  }

  get resultItems(): ResultItemDef[] {
    if (!this.result) { return []; }
    return [
      { label: 'حجم جابجایی یک سیلندر', value: this.result.sweptVolumePerCylinderCc, unit: 'cc' },
      { label: 'حجم موتور', value: this.result.totalDisplacementCc, unit: 'cc' },
      { label: 'حجم واشر', value: this.result.gasketVolumeCc, unit: 'cc' },
      { label: 'حجم فاصله پیستون تا بلوک', value: this.result.deckVolumeCc, unit: 'cc' },
      { label: 'حجم محفظه در نقطه مرگ بالا', value: this.result.clearanceVolumeCc, unit: 'cc' },
      { label: 'فاصله کوئنچ به اینچ', value: this.result.quenchInches, unit: 'in' },
    ];
  }

  get quenchMarkerPercent(): number {
    if (!this.result) { return 0; }
    return Math.max(0, Math.min(100, this.result.quenchMm / 1.5 * 100));
  }

  async onInfo(type: string): Promise<void> {
    const messages: Record<string, string> = {
      bore: 'قطر نهایی داخلی سیلندر پس از ماشین‌کاری، برحسب میلی‌متر.',
      stroke: 'کورس میل‌لنگ، برحسب میلی‌متر.',
      cylinders: 'تعداد سیلندرهای موتور؛ فقط در حجم کل موتور اثر دارد.',
      chamber: 'حجم واقعی اتاق احتراق سرسیلندر برای هر سیلندر، با burette اندازه‌گیری شود.',
      piston: 'حجم گودی یا برجستگی پیستون. گودی را مثبت و برجستگی را منفی وارد کنید.',
      gasketBore: 'قطر داخلی دهانه واشر سرسیلندر پس از نصب.',
      gasketThickness: 'ضخامت فشرده‌شده واشر، نه ضخامت واشر نو پیش از بستن.',
      deck: 'فاصله تاج پیستون تا سطح بلوک در نقطه مرگ بالا. برای پیستون بالاتر از بلوک، عدد منفی وارد کنید.',
    };
    await this.presentInfo(messages[type] || 'توضیحی برای این پارامتر موجود نیست.');
  }

  private async presentInfo(message: string): Promise<void> {
    const alert = await this.alertController.create({ cssClass: 'main-alert', header: 'توضیحات', message, buttons: ['بستن'] });
    await alert.present();
  }

  private cylinderVolumeCc(diameterMm: number, heightMm: number): number {
    return Math.PI / 4 * Math.pow(diameterMm / 10, 2) * (heightMm / 10);
  }

  private round(value: number, decimals: number): number {
    const factor = Math.pow(10, decimals);
    return Math.round((value + Number.EPSILON) * factor) / factor;
  }
}
